//! Audio — background music + event-driven SFX.
//!
//! Bundle 4bk wired one Sci-Fi loop track at startup.
//! Bundle 4bl loads pre-baked SFX (generated by
//! `tools/gen_sfx.py` from the Godot client's
//! `procedural_audio.gd`) and wires:
//!
//! - **Click** on every egui mouse-down — pitched variant from a
//!   six-step pentatonic chain that walks up on rapid presses and
//!   resets to root after a 1.2 s cooldown. Mirrors the Godot
//!   "rapid clicks build a melody" behavior exactly.
//! - **Explosion** when a ship is decommissioned (broke / hoard /
//!   admin destroy). Three sizes baked; chooses by ship class as a
//!   rough proxy for hull mass (courier → small, hauler → large).
//! - **Gate-jump ping** when a ship traverses a jump gate.
//!
//! All SFX run through Bevy's audio pipeline at `PlaybackSettings::
//! DESPAWN` so they self-clean after their tail finishes.

use bevy::prelude::*;
use rand::Rng;
use std::time::{Duration, Instant};

pub struct AudioPlugin;

impl Plugin for AudioPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<MusicState>()
            .init_resource::<ClickChain>()
            .init_resource::<AudioSettings>()
            .add_systems(Startup, (start_music, load_sfx))
            .add_systems(
                Update,
                (
                    play_click_on_egui_press,
                    play_event_driven_sfx,
                    apply_music_volume,
                ),
            );
    }
}

/// User-tunable audio mix. Both volumes are linear 0..=1; the
/// effective egui slider default lands roughly where the previous
/// hard-coded baselines sat. Persists in-memory only — Bundle 4br
/// will hook this up to disk alongside the save-list work.
#[derive(Resource)]
pub struct AudioSettings {
    pub music_volume: f32,
    pub sfx_volume: f32,
}

impl Default for AudioSettings {
    fn default() -> Self {
        Self {
            // Matches the previous music spawn volume so first-boot
            // sounds the same as Bundle 4bk did.
            music_volume: 0.45,
            // SFX baseline — the per-effect volume passed to
            // PlaybackSettings is multiplied by this so users can
            // tame loud one-shots without zeroing music too.
            sfx_volume: 0.6,
        }
    }
}

// ---------------------------------------------------------------------------
// Music — random Sci-Fi loop track on boot
// ---------------------------------------------------------------------------

#[derive(Resource, Default)]
pub struct MusicState {
    pub entity: Option<Entity>,
}

const TRACKS: &[&str] = &[
    "music/Sci-Fi 1 Loop.ogg",
    "music/Sci-Fi 2 Loop.ogg",
    "music/Sci-Fi 3 Loop.ogg",
    "music/Sci-Fi 4 Loop.ogg",
    "music/Sci-Fi 5 Loop.ogg",
    "music/Sci-Fi 6 Loop.ogg",
    "music/Sci-Fi 7 Loop.ogg",
    "music/Sci-Fi 8 Loop.ogg",
];

fn start_music(
    asset_server: Res<AssetServer>,
    mut commands: Commands,
    mut state: ResMut<MusicState>,
    settings: Res<AudioSettings>,
) {
    let mut rng = rand::thread_rng();
    let idx = rng.gen_range(0..TRACKS.len());
    let path = TRACKS[idx];
    info!("client_bevy: starting background music — {}", path);

    let entity = commands
        .spawn((
            AudioPlayer::<AudioSource>(asset_server.load(path)),
            PlaybackSettings {
                mode: bevy::audio::PlaybackMode::Loop,
                volume: bevy::audio::Volume::Linear(settings.music_volume),
                ..default()
            },
        ))
        .id();
    state.entity = Some(entity);
}

/// Per-frame: when `AudioSettings.music_volume` changes (Options
/// slider), push the new value into the music entity's `AudioSink`
/// so the change is heard immediately rather than waiting for the
/// track to loop. Cheap — only mutates when the resource is
/// `is_changed()`.
fn apply_music_volume(
    settings: Res<AudioSettings>,
    music: Res<MusicState>,
    mut sinks: Query<&mut bevy::audio::AudioSink>,
) {
    if !settings.is_changed() {
        return;
    }
    let Some(entity) = music.entity else { return };
    let Ok(mut sink) = sinks.get_mut(entity) else { return };
    sink.set_volume(bevy::audio::Volume::Linear(settings.music_volume));
}

// ---------------------------------------------------------------------------
// SFX library — pre-baked WAVs from `tools/gen_sfx.py`
// ---------------------------------------------------------------------------

#[derive(Resource)]
pub struct SfxLibrary {
    pub explosion_small: Handle<AudioSource>,
    pub explosion_med: Handle<AudioSource>,
    pub explosion_large: Handle<AudioSource>,
    /// Pentatonic chain click variants (6 steps).
    pub click_steps: [Handle<AudioSource>; 6],
    pub gate_jump: Handle<AudioSource>,
    #[allow(dead_code)]
    pub close: Handle<AudioSource>,
    #[allow(dead_code)]
    pub confirm: Handle<AudioSource>,
    #[allow(dead_code)]
    pub deny: Handle<AudioSource>,
    #[allow(dead_code)]
    pub warn: Handle<AudioSource>,
    #[allow(dead_code)]
    pub select: Handle<AudioSource>,
}

fn load_sfx(asset_server: Res<AssetServer>, mut commands: Commands) {
    commands.insert_resource(SfxLibrary {
        explosion_small: asset_server.load("sfx/explosion_small.ogg"),
        explosion_med: asset_server.load("sfx/explosion_med.ogg"),
        explosion_large: asset_server.load("sfx/explosion_large.ogg"),
        click_steps: [
            asset_server.load("sfx/click_0.ogg"),
            asset_server.load("sfx/click_1.ogg"),
            asset_server.load("sfx/click_2.ogg"),
            asset_server.load("sfx/click_3.ogg"),
            asset_server.load("sfx/click_4.ogg"),
            asset_server.load("sfx/click_5.ogg"),
        ],
        gate_jump: asset_server.load("sfx/gate_jump.ogg"),
        close: asset_server.load("sfx/close.ogg"),
        confirm: asset_server.load("sfx/confirm.ogg"),
        deny: asset_server.load("sfx/deny.ogg"),
        warn: asset_server.load("sfx/warn.ogg"),
        select: asset_server.load("sfx/select.ogg"),
    });
}

// ---------------------------------------------------------------------------
// Click chain — pentatonic walk-up + cooldown reset
// ---------------------------------------------------------------------------

/// Mirrors the Godot client's CLICK_CHAIN_WINDOW_MS = 1200. Every
/// click within this window from the previous one bumps step+1 mod
/// pentatonic-length; pausing longer resets to root. Charm detail
/// — rapid UI presses build a little tune, then reset to neutral
/// when the user pauses.
const CLICK_CHAIN_WINDOW: Duration = Duration::from_millis(1200);

#[derive(Resource, Default)]
pub struct ClickChain {
    step: usize,
    last_click: Option<Instant>,
}

impl ClickChain {
    /// Advance the chain — call once per click. Returns the step
    /// (0..6) to use for picking the click variant.
    fn next_step(&mut self) -> usize {
        let now = Instant::now();
        let in_window = self
            .last_click
            .map(|t| now.duration_since(t) < CLICK_CHAIN_WINDOW)
            .unwrap_or(false);
        if in_window {
            self.step = (self.step + 1) % 6;
        } else {
            self.step = 0;
        }
        self.last_click = Some(now);
        self.step
    }
}

/// Listen for left-mouse clicks that landed on egui chrome and play
/// the next pentatonic-chain click variant. World clicks (raycasts
/// for selection) DON'T fire — they aren't UI presses.
///
/// Detection uses `wants_pointer_input()` rather than
/// `is_pointer_over_area()`. The latter only registers floating
/// Windows / Areas; clicks on TopBottomPanel chrome (the always-on
/// top bar) returned false, so panel-toggle buttons up there were
/// silent. `wants_pointer_input()` is true whenever egui claims the
/// pointer for hover/drag/click — covers panels, windows, dropdown
/// pop-ups, sliders, tooltips. The only false-positive is
/// click-on-empty-panel-space, which is a rare-enough motion to
/// trade for getting top bar clicks to chime.
#[allow(clippy::too_many_arguments)]
fn play_click_on_egui_press(
    mut ctx: bevy_egui::EguiContexts,
    buttons: Res<ButtonInput<MouseButton>>,
    sfx: Option<Res<SfxLibrary>>,
    settings: Res<AudioSettings>,
    mut chain: ResMut<ClickChain>,
    mut commands: Commands,
) {
    let Some(sfx) = sfx else { return };
    if !buttons.just_pressed(MouseButton::Left) {
        return;
    }
    if !ctx.ctx_mut().wants_pointer_input() {
        return;
    }
    let step = chain.next_step();
    commands.spawn((
        AudioPlayer::<AudioSource>(sfx.click_steps[step].clone()),
        PlaybackSettings {
            mode: bevy::audio::PlaybackMode::Despawn,
            volume: bevy::audio::Volume::Linear(0.35 * settings.sfx_volume),
            ..default()
        },
    ));
}

// ---------------------------------------------------------------------------
// Event-driven SFX — read sim's events log + fire one-shots
// ---------------------------------------------------------------------------

/// Per-frame: drain new entries from `EventsLog` and play the
/// matching SFX. High-water `Local<u64>` tick mark mirrors the
/// pattern `event_driven_flashes` in render uses, so we don't
/// re-play sounds for events already heard.
fn play_event_driven_sfx(
    events: Res<crate::sim::EventsLog>,
    sfx: Option<Res<SfxLibrary>>,
    settings: Res<AudioSettings>,
    mut last_tick: Local<u64>,
    mut commands: Commands,
) {
    let Some(sfx) = sfx else { return };
    if events.0.is_empty() {
        return;
    }

    let mut new_high = *last_tick;
    for (tick, ev) in events.0.iter() {
        if *tick <= *last_tick {
            continue;
        }
        if *tick > new_high {
            new_high = *tick;
        }
        let kind = ev.get("kind").and_then(|k| k.as_str()).unwrap_or("");
        match kind {
            "ship_decommissioned" => {
                // Pick explosion size from ship class. Couriers
                // pop, haulers thunder. Default to medium for
                // anything we don't recognise.
                let class = ev.get("class").and_then(|c| c.as_str()).unwrap_or("");
                let source = match class {
                    "courier" | "miner" => sfx.explosion_small.clone(),
                    "hauler" => sfx.explosion_large.clone(),
                    _ => sfx.explosion_med.clone(),
                };
                commands.spawn((
                    AudioPlayer::<AudioSource>(source),
                    PlaybackSettings {
                        mode: bevy::audio::PlaybackMode::Despawn,
                        volume: bevy::audio::Volume::Linear(0.6 * settings.sfx_volume),
                        ..default()
                    },
                ));
            }
            "ship_gate_jumped" => {
                commands.spawn((
                    AudioPlayer::<AudioSource>(sfx.gate_jump.clone()),
                    PlaybackSettings {
                        mode: bevy::audio::PlaybackMode::Despawn,
                        volume: bevy::audio::Volume::Linear(0.4 * settings.sfx_volume),
                        ..default()
                    },
                ));
            }
            _ => {}
        }
    }
    *last_tick = new_high;
}
